-- Biblioteca inicial de exercícios (pode ser editada pelo usuário).
-- Os campos servem apenas para busca/organização; não indicam equivalência biomecânica.

-- Sugestões organizacionais (não são equivalências garantidas).
SELECT a.id, b.id, 'Mesmo grupo muscular e padrão de movimento'
FROM exercise a JOIN exercise b
  ON a.id <> b.id AND a.muscle_focus = b.muscle_focus AND a.movement_pattern = b.movement_pattern
WHERE a.muscle_focus <> 'Cardio';
